    static string root="";static readonly List<string> passed=[];
    static void Assert(bool value,string message){if(!value)throw new Exception(message);passed.Add(message);Console.WriteLine("PASS: "+message);}
    static async Task Until(Func<bool> predicate,int seconds=30){var limit=DateTime.UtcNow.AddSeconds(seconds);while(!predicate()){if(DateTime.UtcNow>limit)throw new TimeoutException("Condition timed out.");await Task.Delay(100);}}
    static void Shot(Window window,string name){window.UpdateLayout();var size=new Size(window.ActualWidth,window.ActualHeight);var dpi=VisualTreeHelper.GetDpi(window);Visual visual=window;if(window is SettingsWindow&&window.Content is FrameworkElement content){size=new Size(content.ActualWidth,content.ActualHeight);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen()){dc.DrawRectangle(window.Background,null,new Rect(new Point(),size));dc.DrawRectangle(new VisualBrush(content),null,new Rect(new Point(),size));}visual=drawing;}var image=new RenderTargetBitmap((int)Math.Ceiling(size.Width*dpi.DpiScaleX),(int)Math.Ceiling(size.Height*dpi.DpiScaleY),dpi.PixelsPerInchX,dpi.PixelsPerInchY,PixelFormats.Pbgra32);image.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var f=File.Create(Path.Combine(root,name+".png"));png.Save(f);Console.WriteLine("SCREENSHOT: "+name);}
    static bool Alive(int pid){try{return !Process.GetProcessById(pid).HasExited;}catch(ArgumentException){return false;}}
