    static async Task Run(){
        var settings=AppSettings.Detect();settings.Workspace=Path.Combine(root,"workspace");settings.Validate();var preferences=Path.Combine(root,"preferences");Files.Write(Path.Combine(preferences,"preferences.json"),new Preferences{Settings=settings,Language="zh"});
