        vm.ExampleCommand.Execute("wonder");Assert(vm.Prompt.Contains("capybara"),"Example inserts prompt");var draft=vm.Prompt;vm.SetLanguage("en");await Task.Delay(300);Assert(vm.Prompt==draft&&vm.T["New creation"]=="New creation","Language switch preserves draft");Shot(window,"welcome-en");vm.SetLanguage("zh");
        var settingsWindow=new SettingsWindow(vm){Owner=window};settingsWindow.Show();await Task.Delay(200);Shot(settingsWindow,"settings");settingsWindow.Close();
        foreach(var ratio in Presets.Ratios)for(int tier=0;tier<3;tier++){var (w,h)=Presets.Dimensions(tier,ratio);Assert(w%32==0&&h%32==0&&w>=384&&h>=384,"Valid preset "+tier+" "+ratio);}
        vm.RandomSeed=false;vm.Seed="-1";await vm.GenerateAsync();Assert(!vm.IsRunning&&vm.Recent.Count==0,"Invalid seed rejected before starting backend");vm.Seed="42";
        var cancelledTask=vm.GenerateAsync();await Until(()=>vm.Turns.Count>0&&vm.Turns[^1].BackendPid>0,30);var cancelled=vm.Turns[^1];await Task.Delay(5000);await vm.StopAsync();await cancelledTask;Assert(cancelled.Status=="cancelled"&&!Alive(cancelled.BackendPid),"Cancel terminates owned inference process");
        Assert(File.Exists(Path.Combine(cancelled.Directory,"request.json")),"Cancelled request retained");
        vm.NewCreation();vm.ExampleCommand.Execute("wonder");vm.Tier=0;vm.Ratio="4:3";var smallTask=vm.GenerateAsync();await smallTask;var small=vm.Turns[^1];Assert(small.Completed,"Real 512-tier generation completes");Assert(ImageLoader.Load(small.Request.Output,0).PixelWidth==576,"Real landscape dimensions match preset");Shot(window,"completed-512");
        vm.NewCreation();vm.ExampleCommand.Execute("wonder");vm.Tier=1;vm.Ratio="1:1";var task=vm.GenerateAsync();await Until(()=>vm.Turns.Count>0,10);var generated=vm.Turns[^1];await Until(()=>generated.Step>=3||!vm.IsRunning,180);Assert(vm.IsRunning&&generated.Step>=3,"Real sampling progress reaches the UI");Shot(window,"generating");vm.SetLanguage("en");Assert(vm.IsRunning&&generated.Id==vm.Turns[^1].Id,"Language switch preserves active job");vm.SetLanguage("zh");await task;
        Assert(generated.Completed,"Real 1K generation completes");var image=ImageLoader.Load(generated.Request.Output,0);Assert(image.PixelWidth==1024&&image.PixelHeight==1024,"Completed preview is a valid 1024 PNG");Assert(generated.Step==8,"UI receives all eight denoising steps");Assert(!Alive(generated.BackendPid),"Completed inference process exits");Assert(new[]{"request.json","config.json","invocation.json","generation.json","inference.log","image.png"}.All(f=>File.Exists(Path.Combine(generated.Directory,f))),"Reproducible artifacts saved");await Task.Delay(500);Shot(window,"completed-1k");
        vm.ReuseCommand.Execute(generated);Assert(vm.Prompt==generated.Request.Prompt&&vm.Seed=="42"&&!vm.RandomSeed&&vm.SizeText=="1024 × 1024 px","Reuse restores prompt, size and seed");vm.ShowInspector=false;await Task.Delay(200);Shot(window,"completed-wide");vm.ShowInspector=true;
        using(var restored=new MainViewModel(preferences)){Assert(restored.Recent.Count==3,"History restored from disk");restored.Selected=restored.Recent.First(g=>g.Id==generated.Id);Assert(restored.Turns.Count==1&&restored.Turns[0].Completed,"Selection restores completed image");restored.RemoveCommand.Execute(restored.Recent.First(g=>g.Id==cancelled.Id));Assert(restored.Recent.Count==2&&File.Exists(Path.Combine(cancelled.Directory,"request.json")),"Remove history preserves generated files");}
        var recovery=Path.Combine(root,"recovery");var recoveredSettings=settings.Clone();recoveredSettings.Workspace=recovery;Directory.CreateDirectory(recovery);Files.Write(Path.Combine(recovery,"workspace.json"),new WorkspaceState{Generations=[new Generation{Directory=Path.Combine(recovery,"outputs","interrupted"),CreationId="interrupted",Request=new(){Prompt="Interrupted test"}}]});var recoveryPrefs=Path.Combine(root,"recovery-preferences");Files.Write(Path.Combine(recoveryPrefs,"preferences.json"),new Preferences{Settings=recoveredSettings});using(var recovered=new MainViewModel(recoveryPrefs)){Assert(recovered.Recent.Single().Status=="interrupted","Unfinished generation recovers as interrupted");}
        window.Close();
    }
    static async Task FinalRun(string fixture){
        var settings=AppSettings.Detect();settings.Workspace=Path.Combine(root,"workspace");var prefs=Path.Combine(root,"preferences");Files.Write(Path.Combine(prefs,"preferences.json"),new Preferences{Settings=settings});
        using(var vm=new MainViewModel(prefs)){
