            var example=Descendants<Button>(window).First(b=>System.Windows.Automation.AutomationProperties.GetAutomationId(b)=="ExampleWonder");example.Command!.Execute(example.CommandParameter);Assert(vm.Prompt.Contains("capybara"),"Example button binding works");vm.SetLanguage("en");await Task.Delay(200);Shot(window,"welcome-en");vm.SetLanguage("zh");var dialog=new SettingsWindow(vm){Owner=window};dialog.Show();await Task.Delay(200);Shot(dialog,"settings");dialog.Close();
            var invalid=Path.Combine(root,"invalid-request.json");Files.Write(invalid,new{protocol=2});bool rejected=false;using(var client=new BridgeClient()){var code=await client.RunAsync(settings.Python,"check",invalid,Path.Combine(settings.Workspace,"tmp"),e=>{if(e.GetProperty("type").GetString()=="error")rejected=true;});Assert(rejected&&code!=0,"Unsupported backend protocol rejected");}
