        }
        var history=Files.Read<WorkspaceState>(Path.Combine(settings.Workspace,"workspace.json"))!;var baseline=Files.Read<WorkspaceState>(fixture)!;history.Generations.AddRange(baseline.Generations.Where(g=>g.Completed));Files.Write(Path.Combine(settings.Workspace,"workspace.json"),history);
