            vm.NewCreation();vm.ExampleCommand.Execute("nature");var task=vm.GenerateAsync();await Until(()=>vm.Turns.Count>0&&vm.Turns[^1].BackendPid>0,30);var cancelled=vm.Turns[^1];window.Close();await task;await Until(()=>!window.IsVisible,15);Assert(cancelled.Status=="cancelled"&&!Alive(cancelled.BackendPid),"Closing window stops owned inference and closes without recursion");
        }
    }
    static IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T match)yield return match;foreach(var item in Descendants<T>(child))yield return item;}}

